#!/usr/bin/env bash
# plugins-src-guard.sh — pre-commit helper (#3499)
#
# plugins/ is generated by `npm run build` from src/. A staged
# plugins/ork/skills/<s>/<f> without the matching src/skills/<s>/<f> in the
# same commit is either an edit made directly in generated output (lost on
# the next build — hit for real on #3495) or a src/ change the author forgot
# to stage. Today only the CI drift gate catches either case, and it fires
# after the contributor has already pushed. This check is the local tripwire:
# pure path comparison over the staged file list. No build, milliseconds.
#
# Input: one staged path per line on stdin. The pre-commit hook pipes
# `git diff --cached --name-only`; tests pipe fixture lists.
#
# Exit 0 when every plugins/ork/skills/ path has its src/skills/ counterpart
# staged (or none are staged at all). Exit 1 otherwise, printing each
# offender and the exact src/ path to edit instead.
#
# A counterpart also counts when it changed EARLIER on the branch. The
# pre-commit hook passes those paths, one per line, in
# PLUGINS_SRC_GUARD_BRANCH_FILES (git diff of the merge base with the default
# branch against HEAD). Without it a branch could never commit a regen for
# src/ edits made in an earlier commit (#4661: regen alone exit 1, regen plus
# the 3 src files exit 0). Unset or empty keeps the same-commit rule.
#
# Exception: a staged generator input (the build script itself, a build
# helper under scripts/lib/, or a manifest) means the plugins/ diff is
# plausibly REGENERATED output, not a hand edit — generator changes
# legitimately alter built files with no src/skills/ counterpart (hit for
# real on #4147, which dropped a frontmatter key in the build and could not
# commit its own rebuild). Other scripts/ files (eval, docs generation,
# release tooling) do not produce plugins/ output, so they do not exempt.
# The CI Build drift gate still diffs a real build, so a bundled hand edit
# is not invisible.

set -uo pipefail

list=$(cat)
branch_list="${PLUGINS_SRC_GUARD_BRANCH_FILES:-}"

if grep -Eq '^(scripts/build-plugins\.sh|scripts/lib/|manifests/)' <<< "$list"; then
  exit 0
fi

mismatch=0
while IFS= read -r f; do
  case "$f" in
    plugins/ork/skills/*)
      src="src/skills/${f#plugins/ork/skills/}"
      # grep against a here-string, never a pipe: -q early-exits and would
      # SIGPIPE a producer, flipping the test under pipefail (#603).
      if ! grep -Fxq "$src" <<< "$list" && ! grep -Fxq "$src" <<< "$branch_list"; then
        if [[ $mismatch -eq 0 ]]; then
          echo "Generated output staged without its src/ counterpart (plugins/ is built from src/):"
        fi
        echo "  $f"
        echo "    -> edit and stage $src instead (or commit it earlier on this branch)"
        mismatch=$((mismatch + 1))
      fi
      ;;
  esac
done <<< "$list"

[[ $mismatch -gt 0 ]] && exit 1
exit 0
